function parseInput(descriptor, input) {
	if (!descriptor.acceptsInput) return void 0;
	if (!input) {
		if (descriptor.inputRequired) throw new ApiCliError("MISSING_INPUT", "Command requires a single inline JSON input argument", { command: `mastra api ${descriptor.name}` });
		return;
	}
	try {
		const parsed = JSON.parse(input);
		if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new ApiCliError("INVALID_JSON", "Input JSON must be an object");
		return parsed;
	} catch (error) {
		if (error instanceof ApiCliError) throw error;
		throw new ApiCliError("INVALID_JSON", "Input must be valid JSON", { message: error instanceof Error ? error.message : String(error) });
	}
}
function resolvePathParams(descriptor, positionalValues, input) {
	const params = {};
	descriptor.positionals.forEach((name, index) => {
		const value = positionalValues[index];
		if (!value) throw new ApiCliError("MISSING_ARGUMENT", `Missing required argument <${name}>`, { argument: name });
		params[name] = value;
	});
	for (const name of pathParamNames(descriptor.path)) {
		if (params[name]) continue;
		const value = input?.[name];
		if (typeof value !== "string" || !value) throw new ApiCliError("MISSING_ARGUMENT", `Missing required argument <${name}>`, { argument: name });
		params[name] = value;
	}
	return params;
}
function stripPathParamsFromInput(input, params) {
	if (!input) return void 0;
	const copy = { ...input };
	for (const key of Object.keys(params)) delete copy[key];
	return copy;
}
function pathParamNames(path) {
	return Array.from(path.matchAll(/:([A-Za-z0-9_]+)/g)).map((match) => match[1]);
}
