//#region src/commands/server/deploy.ts
function getPackageName(projectDir) {
	try {
		const raw = execSync("node -p \"require('./package.json').name\"", {
			cwd: projectDir,
			encoding: "utf-8",
			stdio: [
				"pipe",
				"pipe",
				"pipe"
			]
		}).trim();
		return raw.startsWith("@") ? raw.split("/")[1] ?? raw : raw;
	} catch {
		return null;
	}
}
async function zipOutput(projectDir, workersManifestOverride) {
	const outputDir = join(projectDir, ".mastra", "output");
	const tmpDir = join(tmpdir(), "mastra-deploy");
	await mkdir(tmpDir, { recursive: true });
	const zipPath = join(tmpDir, `server-deploy-${Date.now()}.zip`);
	return new Promise((resolvePromise, reject) => {
		const output = createWriteStream(zipPath);
		const archive = new ZipArchive({ zlib: { level: 6 } });
		output.on("close", () => resolvePromise(zipPath));
		archive.on("error", reject);
		archive.pipe(output);
		const ignore = ["node_modules/**"];
		if (workersManifestOverride !== void 0) ignore.push("workers.json");
		archive.glob("**", {
			cwd: outputDir,
			ignore,
			dot: true
		}, { prefix: ".mastra/output" });
		if (workersManifestOverride !== void 0) archive.append(workersManifestOverride, { name: ".mastra/output/workers.json" });
		archive.file(join(projectDir, "package.json"), { name: "package.json" });
		archive.finalize();
	});
}
function parseEnvFile(content) {
	const vars = {};
	for (const line of content.split("\n")) {
		const trimmed = line.trim();
		if (!trimmed || trimmed.startsWith("#")) continue;
		const eqIdx = trimmed.indexOf("=");
		if (eqIdx === -1) continue;
		let key = trimmed.slice(0, eqIdx).trim();
		if (key.startsWith("export ")) key = key.slice(7).trim();
		let value = trimmed.slice(eqIdx + 1).trim();
		if (value.startsWith("\"") && value.endsWith("\"") || value.startsWith("'") && value.endsWith("'")) value = value.slice(1, -1);
		if (key) vars[key] = value;
	}
	return vars;
}
/**
* Loads MASTRA_PROJECT_ID and MASTRA_ORG_ID from the project's .env files
* into process.env so deploys auto-link to the project that `mastra init --observability`
* provisioned. Uses dotenv with override: false (the default), so any
* existing process.env value (e.g. from CI) always wins.
*/
function loadDeployEnvFromDotenv(projectDir) {
	config({
		path: [
			join(projectDir, ".env"),
			join(projectDir, ".env.local"),
			join(projectDir, ".env.production")
		],
		quiet: true
	});
}
async function getDeployEnvFiles(projectDir) {
	return (await readdir(projectDir, { withFileTypes: true })).filter((entry) => (entry.isFile() || entry.isSymbolicLink()) && (entry.name === ".env" || entry.name.startsWith(".env.")) && !entry.name.endsWith(".example")).map((entry) => entry.name).sort((a, b) => a.localeCompare(b));
}
async function readEnvVars(projectDir, options = {}) {
	if (options.envFile) {
		const filePath = join(projectDir, options.envFile);
		try {
			await access(filePath);
		} catch {
			throw new Error(`Env file not found: ${options.envFile}`);
		}
		p.log.step(`Using env file: ${options.envFile}`);
		return parseEnvFile(await readFile(filePath, "utf-8"));
	}
	const availableDeployEnvFiles = await getDeployEnvFiles(projectDir);
	if (availableDeployEnvFiles.length === 0) throw new Error("No env file found for deploy. Add a .env or .env.* file before deploying.");
	let selectedEnvFile;
	if (availableDeployEnvFiles.length === 1) selectedEnvFile = availableDeployEnvFiles[0];
	else if (options.autoAccept) throw new Error(`Multiple env files found: ${availableDeployEnvFiles.join(", ")}. Use --env-file to specify which one to deploy.`);
	else {
		const defaultFile = availableDeployEnvFiles.find((envFile) => envFile === ".env.production") ?? availableDeployEnvFiles[0];
		const selected = await p.select({
			message: "Choose env file to deploy",
			options: availableDeployEnvFiles.map((envFile) => ({
				value: envFile,
				label: envFile
			})),
			initialValue: defaultFile
		});
		if (p.isCancel(selected)) {
			p.cancel("Deploy cancelled.");
			process.exit(0);
		}
		selectedEnvFile = selected;
	}
	p.log.step(`Using env file: ${selectedEnvFile}`);
	return parseEnvFile(await readFile(join(projectDir, selectedEnvFile), "utf-8"));
}
async function resolveOrg(token, projectConfig, flagOrg) {
	const isHeadless = Boolean(process.env.MASTRA_API_TOKEN);
	const envOrgId = process.env.MASTRA_ORG_ID;
	if (envOrgId) return {
		orgId: envOrgId,
		orgName: envOrgId
	};
	if (flagOrg) return {
		orgId: flagOrg,
		orgName: (await fetchOrgs(token)).find((o) => o.id === flagOrg)?.name ?? flagOrg
	};
	if (projectConfig?.organizationId) {
		if (isHeadless) return {
			orgId: projectConfig.organizationId,
			orgName: projectConfig.organizationId
		};
		const match = (await fetchOrgs(token)).find((o) => o.id === projectConfig.organizationId);
		if (match) return {
			orgId: match.id,
			orgName: match.name
		};
	}
	const currentOrgId = await getCurrentOrgId();
	const orgs = await fetchOrgs(token);
	if (currentOrgId) {
		const match = orgs.find((o) => o.id === currentOrgId);
		if (match) return {
			orgId: match.id,
			orgName: match.name
		};
	}
	if (orgs.length === 1) return {
		orgId: orgs[0].id,
		orgName: orgs[0].name
	};
	if (orgs.length === 0) throw new Error(`No organizations found. Create one at ${MASTRA_STUDIO_URL}`);
	const selected = await p.select({
		message: "Select an organization",
		options: orgs.map((o) => ({
			value: o.id,
			label: `${o.name} (${o.id})`
		}))
	});
	if (p.isCancel(selected)) {
		p.cancel("Deploy cancelled.");
		process.exit(0);
	}
	const selectedOrg = orgs.find((o) => o.id === selected);
	return {
		orgId: selectedOrg.id,
		orgName: selectedOrg.name
	};
}
async function resolveProject(token, orgId, projectConfig, flagProject, defaultName, autoAccept, isFactoryProject = false) {
	const createProjectNamed = async (name) => {
		const created = isFactoryProject ? await createServerProject(token, orgId, name, { factoryEnabled: true }) : await createServerProject(token, orgId, name);
		p.log.success(`Created ${isFactoryProject ? "Factory project" : "project"} "${created.name}"`);
		return {
			projectId: created.id,
			projectName: created.name,
			projectSlug: created.slug ?? created.name
		};
	};
	const envProjectId = process.env.MASTRA_PROJECT_ID;
	if (envProjectId) return {
		projectId: envProjectId,
		projectName: envProjectId,
		projectSlug: envProjectId
	};
	if (flagProject) {
		const projects = await fetchServerProjects(token, orgId);
		const byId = projects.find((proj) => proj.id === flagProject);
		const bySlug = projects.find((proj) => proj.slug === flagProject);
		const byName = projects.filter((proj) => proj.name === flagProject);
		if (!byId && !bySlug && byName.length > 1) {
			p.cancel(`Multiple projects are named "${flagProject}". Pass --project with the project id or slug to disambiguate.`);
			process.exit(1);
		}
		const match = byId ?? bySlug ?? (byName.length === 1 ? byName[0] : void 0);
		if (match) return {
			projectId: match.id,
			projectName: match.name,
			projectSlug: match.slug ?? match.name
		};
		if (!autoAccept) {
			const confirmed = await p.confirm({ message: `No project named "${flagProject}" found. Create it?` });
			if (p.isCancel(confirmed) || !confirmed) {
				p.cancel("Deploy cancelled.");
				process.exit(0);
			}
		}
		return createProjectNamed(flagProject);
	}
	if (projectConfig?.projectId && projectConfig.organizationId === orgId) return {
		projectId: projectConfig.projectId,
		projectName: projectConfig.projectName ?? projectConfig.projectId,
		projectSlug: projectConfig.projectSlug ?? projectConfig.projectName ?? projectConfig.projectId
	};
	const name = defaultName;
	if (!name) throw new Error("Could not determine project name from package.json. Use --project to specify one.");
	const existing = await fetchServerProjects(token, orgId);
	const nameMatches = existing.filter((proj) => proj.name === name || proj.slug === name);
	if (existing.length > 0) {
		if (autoAccept) {
			if (nameMatches.length === 1) {
				const m = nameMatches[0];
				return {
					projectId: m.id,
					projectName: m.name,
					projectSlug: m.slug ?? m.name
				};
			}
			throw new Error(`Found ${existing.length} existing project(s) in this organization. Pass --project <id-or-slug> to select one, or re-run without --yes to choose interactively.`);
		}
		const CREATE_NEW = "__create_new__";
		const initialValue = nameMatches.length === 1 ? nameMatches[0].id : existing[0].id;
		const selected = await p.select({
			message: "Select a project to deploy to",
			initialValue,
			options: [...existing.map((proj) => ({
				value: proj.id,
				label: `${proj.name} (${proj.id})`
			})), {
				value: CREATE_NEW,
				label: `＋ Create new project "${name}"`
			}]
		});
		if (p.isCancel(selected)) {
			p.cancel("Deploy cancelled.");
			process.exit(0);
		}
		if (selected !== CREATE_NEW) {
			const match = existing.find((proj) => proj.id === selected);
			return {
				projectId: match.id,
				projectName: match.name,
				projectSlug: match.slug ?? match.name
			};
		}
	}
	return createProjectNamed(name);
}
async function serverDeployAction(dir, opts) {
	const analytics = getAnalytics();
	if (!analytics) return runServerDeploy(dir, opts);
	return analytics.trackCommandExecution({
		command: "mastra server deploy",
		args: {
			yes: Boolean(opts.yes),
			skipBuild: Boolean(opts.skipBuild),
			skipPreflight: Boolean(opts.skipPreflight),
			hasOrg: Boolean(opts.org),
			hasProject: Boolean(opts.project),
			hasEnvFile: Boolean(opts.envFile),
			hasConfig: Boolean(opts.config),
			debug: Boolean(opts.debug),
			headless: Boolean(process.env.MASTRA_API_TOKEN),
			targetApi: bucketApiHost(MASTRA_PLATFORM_API_URL)
		},
		execution: () => runServerDeploy(dir, opts),
		origin: process.env.MASTRA_ANALYTICS_ORIGIN
	});
}
async function runServerDeploy(dir, opts) {
	const targetDir = resolve(dir || process.cwd());
	loadDeployEnvFromDotenv(targetDir);
	const isHeadless = Boolean(process.env.MASTRA_API_TOKEN);
	const autoAccept = opts.yes ?? isHeadless;
	const skipPreflight = opts.skipPreflight || process.env.MASTRA_SKIP_PREFLIGHT === "1";
	p.intro("mastra server deploy");
	const packageName = getPackageName(targetDir);
	const isFactoryProject = await detectProjectType(targetDir) === "factory";
	let token;
	try {
		token = await getToken();
	} catch {
		p.log.error(`Authentication failed. Run: mastra auth login`);
		process.exit(1);
	}
	const projectConfig = await loadProjectConfig(targetDir, opts.config);
	const hasOrg = Boolean(process.env.MASTRA_ORG_ID || opts.org || projectConfig?.organizationId);
	const hasProject = Boolean(process.env.MASTRA_PROJECT_ID || opts.project || projectConfig?.projectId);
	if (isHeadless && (!hasOrg || !hasProject)) throw new Error("MASTRA_ORG_ID and MASTRA_PROJECT_ID (or --org/--project flags, or .mastra-project.json) are required when MASTRA_API_TOKEN is set");
	const { orgId, orgName } = await resolveOrg(token, projectConfig, opts.org);
	const { projectId, projectName, projectSlug } = await resolveProject(token, orgId, projectConfig, opts.project, packageName, autoAccept, isFactoryProject);
	if (!(projectConfig?.projectId === projectId && projectConfig?.organizationId === orgId)) {
		p.note([
			`Organization:  ${orgName}`,
			`Project:       ${projectName}`,
			`Directory:     ${targetDir}`
		].join("\n"), "Deploy settings");
		if (!autoAccept) {
			const confirmed = await p.confirm({ message: "Deploy with these settings?" });
			if (p.isCancel(confirmed) || !confirmed) {
				p.cancel("Deploy cancelled.");
				process.exit(0);
			}
		}
		await saveProjectConfig(targetDir, getProjectConfigToSave(projectId, projectName, projectSlug, orgId, projectConfig), opts.config);
		p.log.success(`Saved ${opts.config || ".mastra-project.json"}`);
	} else {
		p.log.info(`Organization: ${orgName} (${orgId})`);
		p.log.info(`Project: ${projectName} (${projectId})`);
	}
	const s = p.spinner();
	const staleness = await checkBuildStaleness(targetDir, join(targetDir, "src", "mastra"), join(targetDir, ".mastra"));
	if (opts.skipBuild) {
		if (staleness.isStale && staleness.reason !== "no-build") {
			if (staleness.reason === "hash-mismatch") p.log.warn("Source files have changed since last build. Deploy may not reflect latest changes.");
			else if (staleness.reason === "no-manifest") p.log.warn("No build manifest found. Cannot verify if build is up-to-date.");
		}
		p.log.step("Skipping build (--skip-build)");
	} else if (staleness.isStale) {
		if (staleness.reason === "hash-mismatch") p.log.step("Source files changed, rebuilding...");
		await runBuild(targetDir, { debug: opts.debug });
	} else p.log.step("Build is up-to-date, skipping rebuild");
	const outputEntry = join(targetDir, ".mastra", "output", "index.mjs");
	try {
		await access(outputEntry);
	} catch {
		throw new Error(".mastra/output/index.mjs not found — did the build succeed?");
	}
	let envVars = {};
	const hasEnvFile = opts.envFile ? true : (await getDeployEnvFiles(targetDir)).length > 0;
	if (hasEnvFile) envVars = await readEnvVars(targetDir, {
		autoAccept,
		envFile: opts.envFile
	});
	const envCount = Object.keys(envVars).length;
	if (envCount > 0) p.log.step(`Found ${envCount} env var(s)`);
	else if (hasEnvFile) p.log.step("No env vars found in selected env file");
	else p.log.step("No local env file — using env vars stored on the project");
	if (!skipPreflight) {
		let storedEnvVars;
		try {
			storedEnvVars = await getServerProjectEnv(token, orgId, projectId);
		} catch {}
		const outcome = await printPreflightIssues(await preflightBuildOutput(targetDir, mergePreflightEnvVars(storedEnvVars, envVars), {
			hasEnvFile,
			managedEnvVarNames: null
		}), { autoAccept });
		if (outcome === "blocked") {
			p.cancel("Deploy blocked by preflight errors.");
			process.exit(1);
		}
		if (outcome === "cancelled") {
			p.cancel("Deploy cancelled.");
			process.exit(0);
		}
	}
	const workersGuard = await resolveLegacyWorkersManifestOverride(join(targetDir, ".mastra", "output"));
	if (workersGuard.status === "stripped") p.log.info("Background workers run in-process on server deploys — use `mastra deploy` for a dedicated worker service.");
	s.start("Zipping build artifact...");
	const zipPath = await zipOutput(targetDir, workersGuard.manifestOverride);
	const sizeKB = (await stat(zipPath)).size / 1024;
	const sizeLabel = sizeKB > 1024 ? `${(sizeKB / 1024).toFixed(1)}MB` : `${sizeKB.toFixed(1)}KB`;
	s.stop(`Created ${sizeLabel} archive`);
	const zipBuffer = await readFile(zipPath);
	await checkBundleSize({
		artifactBytes: zipBuffer.byteLength,
		outputDir: join(targetDir, ".mastra", "output"),
		warn: (message) => p.log.warn(message)
	});
	s.start("Uploading...");
	const deployResult = await uploadServerDeploy(token, orgId, projectId, zipBuffer, {
		projectName,
		envVars: envCount > 0 ? envVars : void 0,
		disablePlatformObservability: projectConfig?.disablePlatformObservability === true,
		...isFactoryProject ? { factoryEnabled: true } : {}
	});
	s.stop(`Deploy accepted: ${deployResult.id}`);
	await rm(zipPath, { force: true });
	p.log.step("Streaming deploy logs...");
	const collectedLogs = opts.debug ? void 0 : createLogCollector();
	const finalStatus = await pollServerDeploy(deployResult.id, token, orgId, void 0, {
		showAllLogs: opts.debug,
		collectLogs: collectedLogs
	});
	if (finalStatus.status === "running") p.outro(`Deploy succeeded! ${finalStatus.instanceUrl}`);
	else {
		printDeployFailure({
			message: finalStatus.status === "failed" ? `Deploy failed: ${finalStatus.error}` : `Deploy ended with status: ${finalStatus.status}`,
			collectedLogs: collectedLogs?.entries() ?? [],
			dashboardUrl: deployDashboardUrl("server", {
				orgId,
				projectId,
				deployId: deployResult.id
			}),
			showAllLogs: opts.debug
		});
		process.exit(1);
	}
}
